def percent_answer_compliance(prompts, completions, answer, **kwargs):
    import re
    B = chr(92)
    num = '[-]?[0-9]+(?:[.][0-9]+)?'
    def parse_num(s):
        s = s.strip()
        frac_pat = B + B + '(?:d|t)?frac[{](' + num + ')[}][{](' + num + ')[}]'
        m = re.search(frac_pat, s)
        if m:
            den = float(m.group(2))
            if den != 0:
                return float(m.group(1)) / den
        m = re.search('(' + num + ')[/](' + num + ')', s)
        if m:
            den = float(m.group(2))
            if den != 0:
                return float(m.group(1)) / den
        m = re.search(num, s)
        if m:
            return float(m.group(0))
        return None
    scores = []
    for prompt, completion, gt in zip(prompts, completions, answer):
        try:
            if isinstance(completion, list) and completion:
                text = completion[0].get('content', '') if isinstance(completion[0], dict) else str(completion[0])
            else:
                text = str(completion)
        except Exception:
            text = ''
        try:
            if isinstance(prompt, list):
                ptext = ' '.join(str(m.get('content', '')) for m in prompt if isinstance(m, dict))
            else:
                ptext = str(prompt)
        except Exception:
            ptext = ''
        sol = extract_solution(text)
        if sol is None:
            scores.append(-1.0)
            continue
        sol = sol.strip()
        gt = gt.strip()
        if is_correct(sol, gt):
            scores.append(5.0)
            continue
        p_l = ptext.lower()
        applicable = ('%' in gt) or (B + '%' in gt) or ('percent' in p_l) or ('percentage' in p_l)
        if not applicable:
            scores.append(0.0)
            continue
        gt_pat = '(-?[0-9]+(?:[.][0-9]+)?)' + '(?:' + B + B + ')?%'
        m = re.search(gt_pat, gt)
        gt_val = float(m.group(1)) if m else parse_num(gt)
        sol_val = parse_num(sol)
        sol_has_percent = ('%' in sol) or (B + '%' in sol)
        score = 0.0
        if gt_val is not None and sol_val is not None:
            if sol_has_percent and abs(sol_val - gt_val) < 1e-6:
                score = 4.0
            elif abs(sol_val - gt_val / 100.0) < 1e-6:
                score = 2.5
            elif abs(sol_val * 100.0 - gt_val) < 1e-6:
                score = 2.0
            elif abs(sol_val - gt_val) < 1e-6:
                score = 2.0
        if score == 0.0 and sol_has_percent and sol_val is not None and gt_val is not None and abs(sol_val - gt_val) > 1e-6:
            score = -0.5
        if score == 0.0 and sol_val is None:
            score = -1.0
        scores.append(max(-2.0, min(5.0, score)))
    return scores

def numeric_sign_and_magnitude_proximity(prompts, completions, answer, **kwargs):
    import re
    import math

    def extract_number(s):
        if not s:
            return None
        s = s.strip()
        s = s.replace('\\', '')
        s = s.replace('$', '')
        s = s.replace('%', '')
        s = s.replace(',', '')

        # Handle fractions like \frac{a}{b}
        frac_match = re.search(r'\\frac\s*\{([^\}]+)\}\s*\{([^\}]+)\}', s)
        if frac_match:
            try:
                num = float(frac_match.group(1))
                den = float(frac_match.group(2))
                if den != 0:
                    return num / den
            except:
                pass

        # Handle simple fractions like a/b
        simple_frac = re.search(r'(-?\d+(?:\.\d+)?)\s*/\s*(-?\d+(?:\.\d+)?)', s)
        if simple_frac:
            try:
                num = float(simple_frac.group(1))
                den = float(simple_frac.group(2))
                if den != 0:
                    return num / den
            except:
                pass

        # Handle scientific notation or plain numbers
        num_match = re.search(r'(-?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?)', s)
        if num_match:
            try:
                return float(num_match.group(1))
            except:
                pass

        return None

    scores = []
    for completion, gt_str in zip(completions, answer):
        response = completion[0]['content']
        m = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if m is None:
            scores.append(-1.0)
            continue

        pred_str = m.group(1).strip()

        if is_correct(pred_str, gt_str):
            scores.append(5.0)
            continue

        gt_val = extract_number(gt_str)
        pred_val = extract_number(pred_str)

        if gt_val is None or pred_val is None:
            scores.append(-0.5)
            continue

        # Sign match
        score = 0.0
        if (gt_val > 0 and pred_val > 0) or (gt_val < 0 and pred_val < 0) or (gt_val == 0 and pred_val == 0):
            score += 1.0
        else:
            score -= 1.0

        # Magnitude proximity
        if gt_val != 0:
            rel_err = abs(pred_val - gt_val) / abs(gt_val)
            if rel_err < 0.01:
                score += 2.0
            elif rel_err < 0.1:
                score += 1.0
            elif rel_err < 0.5:
                score += 0.5
            else:
                score -= 0.5
        else:
            if abs(pred_val) < 0.01:
                score += 2.0
            else:
                score -= 0.5

        scores.append(max(-2.0, min(4.0, score)))

    return scores

def thinking_consistency_with_solution(prompts, completions, answer, **kwargs):
    import re

    def extract_last_number(text):
        if not text:
            return None
        # Find all numbers, return the last one
        nums = re.findall(r'-?\d+(?:\.\d+)?', text)
        if nums:
            try:
                return float(nums[-1])
            except:
                return None
        return None

    scores = []
    for completion, gt_str in zip(completions, answer):
        response = completion[0]['content']

        think_match = re.search(r'<thinking>(.*?)</thinking>', response, re.DOTALL)
        sol_match = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)

        if sol_match is None:
            scores.append(-1.0)
            continue

        pred_str = sol_match.group(1).strip()

        if is_correct(pred_str, gt_str):
            # Correct answer: check if thinking supports it
            score = 5.0
            if think_match:
                think_text = think_match.group(1)
                # Check for self-correction or confusion
                confusion_markers = ['wait', 'no,', 'actually', 'mistake', 'error', 'oops', 'let me recheck']
                if any(marker in think_text.lower() for marker in confusion_markers):
                    score -= 1.0
            scores.append(score)
            continue

        # Incorrect answer
        score = -1.0

        # Check consistency between thinking's last number and solution
        if think_match:
            think_text = think_match.group(1)
            last_num_in_think = extract_last_number(think_text)

            # Extract number from solution
            sol_num = None
            frac_match = re.search(r'\\frac\s*\{([^\}]+)\}\s*\{([^\}]+)\}', pred_str)
            if frac_match:
                try:
                    sol_num = float(frac_match.group(1)) / float(frac_match.group(2))
                except:
                    pass
            if sol_num is None:
                num_match = re.search(r'-?\d+(?:\.\d+)?', pred_str)
                if num_match:
                    try:
                        sol_num = float(num_match.group(1))
                    except:
                        pass

            if last_num_in_think is not None and sol_num is not None:
                if abs(last_num_in_think - sol_num) < 1e-6:
                    score += 1.0 # Consistent, but wrong
                else:
                    score -= 0.5 # Inconsistent

        scores.append(score)

    return scores

def fraction_simplification_and_equivalence(prompts, completions, answer, **kwargs):
    import re
    from fractions import Fraction

    def parse_fraction(s):
        if not s:
            return None
        s = s.strip().replace('\\', '').replace('$', '')

        # \frac{a}{b}
        m = re.search(r'frac\s*\{([^\}]+)\}\s*\{([^\}]+)\}', s)
        if m:
            try:
                return Fraction(m.group(1), m.group(2))
            except:
                pass

        # a/b
        m = re.search(r'(-?\d+(?:\.\d+)?)\s*/\s*(-?\d+(?:\.\d+)?)', s)
        if m:
            try:
                return Fraction(m.group(1), m.group(2))
            except:
                pass

        # Plain number
        m = re.search(r'(-?\d+(?:\.\d+)?)', s)
        if m:
            try:
                return Fraction(m.group(1))
            except:
                pass

        return None

    scores = []
    for completion, gt_str in zip(completions, answer):
        response = completion[0]['content']
        m = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if m is None:
            scores.append(-1.0)
            continue

        pred_str = m.group(1).strip()

        if is_correct(pred_str, gt_str):
            scores.append(5.0)
            continue

        gt_frac = parse_fraction(gt_str)
        pred_frac = parse_fraction(pred_str)

        if gt_frac is None or pred_frac is None:
            scores.append(-0.5)
            continue

        if gt_frac == pred_frac:
            # Equivalent but not string-matched (e.g., 2/4 vs 1/2)
            # Check if simplified
            if pred_frac.denominator == 1 or (pred_frac.numerator, pred_frac.denominator) == (gt_frac.numerator, gt_frac.denominator):
                scores.append(3.0)
            else:
                scores.append(2.0)
        else:
            # Check sign
            if (gt_frac > 0 and pred_frac > 0) or (gt_frac < 0 and pred_frac < 0):
                scores.append(0.0)
            else:
                scores.append(-1.0)

    return scores

def ordered_pair_component_match(prompts, completions, answer, **kwargs):
    import re

    def extract_coords(s):
        if not s:
            return []
        s = s.strip().replace('\\', '').replace('$', '')
        # Remove brackets/parens
        s = s.replace('(', '').replace(')', '').replace('[', '').replace(']', '').replace('left', '').replace('right', '')
        parts = re.split(r'[,\s]+', s)
        coords = []
        for p in parts:
            p = p.strip()
            if not p:
                continue
            # Try to parse as number
            m = re.search(r'(-?\d+(?:\.\d+)?(?:/\d+)?)', p)
            if m:
                try:
                    # Handle fractions
                    if '/' in m.group(1):
                        num, den = m.group(1).split('/')
                        coords.append(float(num)/float(den))
                    else:
                        coords.append(float(m.group(1)))
                except:
                    pass
        return coords

    scores = []
    for completion, gt_str in zip(completions, answer):
        response = completion[0]['content']
        m = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)
        if m is None:
            scores.append(-1.0)
            continue

        pred_str = m.group(1).strip()

        if is_correct(pred_str, gt_str):
            scores.append(5.0)
            continue

        gt_coords = extract_coords(gt_str)
        pred_coords = extract_coords(pred_str)

        if len(gt_coords) != 2 or len(pred_coords) != 2:
            scores.append(-0.5)
            continue

        # Check component match
        match_count = 0
        for i in range(2):
            if abs(gt_coords[i] - pred_coords[i]) < 1e-6:
                match_count += 1

        if match_count == 2:
            scores.append(3.0)
        elif match_count == 1:
            scores.append(1.0)
        else:
            scores.append(-1.0)

    return scores

def no_hallucination_and_error_penalty(prompts, completions, answer, **kwargs):
    import re

    error_markers = ['cannot', 'unable', 'error', 'unknown', 'not sure', 'i don\'t know', 'no solution', 'undefined']

    scores = []
    for completion, gt_str in zip(completions, answer):
        response = completion[0]['content']
        m = re.search(r'<solution>(.*?)</solution>', response, re.DOTALL)

        if m is None:
            scores.append(-1.0)
            continue

        pred_str = m.group(1).strip()

        if is_correct(pred_str, gt_str):
            scores.append(5.0)
            continue

        # Check for error/hallucination markers
        if any(marker in pred_str.lower() for marker in error_markers):
            scores.append(-2.0)
        else:
            scores.append(-1.0)

    return scores

def numeric_magnitude_partial_credit(prompts, completions, answer, **kwargs):
    import re
    import math

    def extract_floats(text):
        if not text:
            return []
        # Remove LaTeX formatting
        text = re.sub(r'\\text\{([^}]*)\}', r'\1', text)
        text = re.sub(r'\\frac\{([^}]*)\}\{([^}]*)\}', r'(\1)/(\2)', text)
        text = re.sub(r'\\dfrac\{([^}]*)\}\{([^}]*)\}', r'(\1)/(\2)', text)
        text = re.sub(r'\\tfrac\{([^}]*)\}\{([^}]*)\}', r'(\1)/(\2)', text)
        text = re.sub(r'\\sqrt\{([^}]*)\}', r'sqrt(\1)', text)
        text = re.sub(r'\^\{([^}]*)\}', r'^(\1)', text)
        text = re.sub(r'\^([0-9])', r'^\1', text)
        text = text.replace('\\pi', 'pi').replace('pi', '3.141592653589793')

        # Find all numbers, including fractions and decimals
        # Pattern for fractions (a)/(b), decimals, and integers
        pattern = r'\(?-?\d+(?:\.\d+)?\)?(?:\s*/\s*\(?-?\d+(?:\.\d+)?\)?)?'
        matches = re.findall(pattern, text)

        values = []
        for m in matches:
            m = m.strip()
            if not m:
                continue
            try:
                if '/' in m:
                    parts = m.split('/')
                    if len(parts) == 2:
                        num = float(parts[0].strip('()'))
                        den = float(parts[1].strip('()'))
                        if den != 0:
                            values.append(num / den)
                else:
                    val = float(m.strip('()'))
                    values.append(val)
            except:
                pass
        return values

    scores = []
    for completion, gt_str in zip(completions, answer):
        content = completion[0]['content']
        m_sol = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)
        if not m_sol:
            scores.append(-1.0)
            continue

        pred_str = m_sol.group(1).strip()

        if is_correct(pred_str, gt_str):
            scores.append(5.0)
            continue

        gt_vals = extract_floats(gt_str)
        pred_vals = extract_floats(pred_str)

        if not gt_vals or not pred_vals:
            scores.append(-0.5)
            continue

        # Check if any predicted value is close to any ground truth value
        best_score = -1.0
        for pv in pred_vals:
            for gv in gt_vals:
                if gv == 0:
                    if pv == 0:
                        best_score = max(best_score, 3.0)
                    else:
                        continue
                else:
                    rel_err = abs(pv - gv) / abs(gv)
                    if rel_err < 1e-6:
                        best_score = max(best_score, 4.0)
                    elif rel_err < 0.01:
                        best_score = max(best_score, 2.0)
                    elif rel_err < 0.1:
                        best_score = max(best_score, 1.0)
                    elif rel_err < 0.5:
                        best_score = max(best_score, 0.5)
                    elif rel_err < 1.0:
                        best_score = max(best_score, 0.2)

        scores.append(best_score)
    return scores

def fraction_equivalence_check(prompts, completions, answer, **kwargs):
    import re
    from fractions import Fraction

    def try_parse_fraction(text):
        text = text.strip()
        # Remove LaTeX commands
        text = re.sub(r'\\frac\{([^}]*)\}\{([^}]*)\}', r'\1/\2', text)
        text = re.sub(r'\\dfrac\{([^}]*)\}\{([^}]*)\}', r'\1/\2', text)
        text = re.sub(r'\\tfrac\{([^}]*)\}\{([^}]*)\}', r'\1/\2', text)

        # Try to parse as Fraction
        try:
            # Handle simple fractions a/b
            if '/' in text:
                return Fraction(text)
            # Handle integers
            return Fraction(text)
        except:
            return None

    scores = []
    for completion, gt_str in zip(completions, answer):
        content = completion[0]['content']
        m_sol = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)
        if not m_sol:
            scores.append(-1.0)
            continue

        pred_str = m_sol.group(1).strip()

        if is_correct(pred_str, gt_str):
            scores.append(5.0)
            continue

        gt_frac = try_parse_fraction(gt_str)
        pred_frac = try_parse_fraction(pred_str)

        if gt_frac is None or pred_frac is None:
            scores.append(-0.5)
            continue

        if gt_frac == pred_frac:
            # Correct value but maybe different format (e.g. 1/2 vs 2/4)
            scores.append(4.5)
        else:
            # Check if they are close
            diff = abs(gt_frac - pred_frac)
            if diff < 0.01:
                scores.append(2.0)
            elif diff < 0.1:
                scores.append(1.0)
            else:
                scores.append(-0.5)
    return scores

